<?php
session_start();
require_once __DIR__ . '/conexion.php';
if (empty($_SESSION['id_usuario']) || ($_SESSION['rol'] ?? '') !== 'administrador') { http_response_code(403); exit('Acceso restringido.'); }
function h($v) { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
if (empty($_SESSION['csrf_tm'])) $_SESSION['csrf_tm'] = bin2hex(random_bytes(32));
function check_post() { if (!hash_equals($_SESSION['csrf_tm'], (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Solicitud inválida'); } }
function num_id($v) { $x=filter_var($v,FILTER_VALIDATE_INT); return $x && $x>0 ? (int)$x : null; }
function opt_id($v) { return ($v === '' || $v === null) ? null : num_id($v); }
function choices($sql) { global $conexion; return $conexion->query($sql)->fetchAll(PDO::FETCH_ASSOC); }
function dt($v) { if (!$v) return null; $d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i', $v); return $d && $d->format('Y-m-d\TH:i') === $v ? $d->format('Y-m-d H:i:s') : false; }
$error='';
$success=isset($_GET['ok']);
$lineas=choices('SELECT id_linea,nombre FROM lineas ORDER BY nombre');$estaciones=choices('SELECT id_estacion,nombre FROM estaciones ORDER BY nombre');$buses=choices('SELECT id_bus,codigo FROM buses ORDER BY codigo');
if ($_SERVER['REQUEST_METHOD']==='POST') {check_post();
 $linea=opt_id($_POST['linea']??'');$est=opt_id($_POST['estacion']??'');$bus=opt_id($_POST['bus']??'');$tipo=$_POST['tipo']??'';$titulo=trim($_POST['titulo']??'');$desc=trim($_POST['descripcion']??'');
 if (!in_array($tipo,['demanda','incidente','servicio'],true) || $titulo==='' || mb_strlen($titulo)>150 || mb_strlen($desc)>5000 || (($_POST['linea']??'')!=='' && !$linea) || (($_POST['estacion']??'')!=='' && !$est) || (($_POST['bus']??'')!=='' && !$bus)) $error='Revisa los datos de la alerta.';
 else {try { $s=$conexion->prepare("INSERT INTO alertas(id_linea,id_estacion,id_bus,tipo,titulo,descripcion,estado) VALUES (?,?,?,?,?,?,'activa')");$s->execute([$linea,$est,$bus,$tipo,$titulo,$desc]);header('Location: alertas_admin.php?ok=1');exit; }catch(PDOException $e){error_log($e->getMessage());$error='No se pudo registrar la alerta.';}}
}
$rows=choices('SELECT a.*,l.nombre AS linea,e.nombre AS estacion,b.codigo AS bus FROM alertas a LEFT JOIN lineas l ON l.id_linea=a.id_linea LEFT JOIN estaciones e ON e.id_estacion=a.id_estacion LEFT JOIN buses b ON b.id_bus=a.id_bus ORDER BY a.id_alerta DESC LIMIT 150');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alertas e incidentes · Transmetro</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f7fb;color:#1c2d45}.navbar{background:#14253e}.card{border:0;border-radius:18px;box-shadow:0 8px 25px #152e4a13}.btn-brand{background:#f0a72e;font-weight:700}.table{font-size:.91rem}</style></head><body><nav class="navbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="panel.php">Transmetro Info</a><a class="btn btn-outline-light btn-sm" href="panel.php">Volver al panel</a></div></nav><main class="container py-5"><h1 class="h2 fw-bold">Alertas e incidentes</h1><p class="text-secondary">Proyecto académico · Datos de demostración</p><?php if ($success): ?><div class="alert alert-success">Registro guardado correctamente.</div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?=h($error)?></div><?php endif; ?><div class="card mb-4"><div class="card-body p-4"><h2 class="h5">Nuevo registro</h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf_tm'])?>"><div class="col-md-6"><label class="form-label">Línea (opcional)</label><select class="form-select" name="linea"  ><option value="">Ninguno</option><?php foreach ($lineas as $v): ?><option value="<?=h($v['id_linea'])?>"><?=h($v['nombre'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Estación (opcional)</label><select class="form-select" name="estacion"  ><option value="">Ninguno</option><?php foreach ($estaciones as $v): ?><option value="<?=h($v['id_estacion'])?>"><?=h($v['nombre'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Bus (opcional)</label><select class="form-select" name="bus"  ><option value="">Ninguno</option><?php foreach ($buses as $v): ?><option value="<?=h($v['id_bus'])?>"><?=h($v['codigo'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Tipo</label><select name="tipo" class="form-select"><option value="incidente">Incidente</option><option value="demanda">Demanda</option><option value="servicio">Servicio</option></select></div><div class="col-md-6"><label class="form-label">Título</label><input class="form-control" type="text" name="titulo" maxlength="150" required></div><div class="col-12"><label class="form-label">Descripción</label><textarea name="descripcion" class="form-control" maxlength="5000" rows="3"></textarea></div><div class="col-12"><button class="btn btn-brand">Guardar</button></div></form></div></div><div class="card"><div class="card-body p-4"><h2 class="h5">Registros</h2><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Fecha</th><th>Tipo</th><th>Título</th><th>Línea</th><th>Estación</th><th>Bus</th><th>Estado</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?=h($r['fecha'])?></td><td><?=h($r['tipo'])?></td><td><?=h($r['titulo'])?></td><td><?=h($r['linea'])?></td><td><?=h($r['estacion'])?></td><td><?=h($r['bus'])?></td><td><?=h($r['estado'])?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7">Aún no hay registros.</td></tr><?php endif; ?></tbody></table></div></div></div></main></body></html>